import {INJURY_CONFIG} from './balance.js';
import {developmentInjuryModifier} from './development.js';
import {random,pick,integer,clamp} from './random.js';
export const INJURIES=[{name:'打撲',min:7,max:14},{name:'足首の捻挫',min:14,max:42},{name:'肉離れ',min:45,max:100},{name:'疲労骨折',min:90,max:180},{name:'膝の靱帯損傷',min:370,max:540,severe:true},{name:'肘靱帯損傷・手術',min:400,max:600,severe:true}];
export function injuryProbability(s){return (INJURY_CONFIG.baseRisk+Math.max(0,s.age-INJURY_CONFIG.agingStart)*INJURY_CONFIG.agingRisk)*developmentInjuryModifier(s);}
export function injury(s){s.injuries??=[];const days=['pro','mlb','independent'].includes(s.stage)?365:122;let current=s.health?.daysLeft>0?s.health:null;let startDay=0;if(!current&&random(s)<injuryProbability(s)){const severe=random(s)<INJURY_CONFIG.severeRisk;const pool=INJURIES.filter(x=>!!x.severe===severe);const spec=pick(s,pool);current={year:s.year,age:s.age,name:spec.name,totalDays:integer(s,spec.min,spec.max),severe,daysLeft:0};current.daysLeft=current.totalDays;if(severe){const keys=s.player.role==='pitcher'?['velocity','control','stamina']:['speed','field','power'];current.decline=integer(s,6,18);for(const k of keys)s.player.abilities[k]=clamp(s.player.abilities[k]-current.decline,5,99);if(random(s)<INJURY_CONFIG.retirementAdviceRisk)s.injuryRetirement=true;}if(['pro','mlb'].includes(s.stage))startDay=integer(s,0,150);s.health=current;s.injuries.push(current);s.timeline.push({year:s.year,text:current.name+'。復帰まで約'+current.totalDays+'日'+(severe?'。大きな能力低下を伴う':'')});}if(!current)return null;const unavailableDays=current.daysLeft;const lost=Math.min(1,current.daysLeft/days);current.daysLeft=Math.max(0,current.daysLeft-(days-startDay));return {...current,lost,startDay,unavailableDays};}
